  document.head.appendChild(style);

  const bot = widget.querySelector("#mv-bot");
  const chatbox = widget.querySelector("#mv-chatbox");
  const input = widget.querySelector("#mv-input");
  const messages = widget.querySelector("#mv-messages");
  const sendBtn = widget.querySelector("#mv-send");
  const headerBar = widget.querySelector("#mv-header-bar");

  const sessionKey = "zeiSessionId";
  let sessionId = localStorage.getItem(sessionKey);
  if (!sessionId) {
    sessionId = "session_" + Date.now() + "_" + Math.random().toString(36).substring(2, 8);
    localStorage.setItem(sessionKey, sessionId);
  }

  bot.addEventListener("click", () => {
    const showing = chatbox.style.display !== "none";
    chatbox.style.display = showing ? "none" : "flex";
    if (!showing && !chatbox.dataset.greeted) {
      appendMessage("Asesor", "¡Hola! 👋 Soy tu asesor comercial de Mobilvendor. ¿En qué puedo ayudarte hoy?");
      chatbox.dataset.greeted = true;
    }
    if (!showing) input.focus();
  });

  input.addEventListener("focus", () => headerBar.classList.add("active"));
  input.addEventListener("blur", () => headerBar.classList.remove("active"));

  function sanitize(text) {
    const div = document.createElement("div");
    div.textContent = String(text ?? "");
    return div.innerHTML;
  }

  // ✅ Sanitizador que permite: <a href="https://...">, <b>, <strong>
  function sanitizeWithLinks(text) {
    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = String(text ?? "");

    const allowed = new Set(["A", "B", "STRONG"]);
    const walker = document.createTreeWalker(tempDiv, NodeFilter.SHOW_ELEMENT, null);

    const toRemove = [];
    while (walker.nextNode()) {
      const el = walker.currentNode;
      if (!allowed.has(el.tagName)) toRemove.push(el);
    }

    // Reemplazar tags no permitidos por texto
    toRemove.forEach((el) => {
      const txt = document.createTextNode(el.textContent || "");
      el.replaceWith(txt);
    });

    // Validar enlaces
    const links = tempDiv.querySelectorAll("a");
    links.forEach((a) => {
      const href = a.getAttribute("href") || "";
      if (!/^https?:\/\//.test(href)) {
        a.replaceWith(document.createTextNode(a.textContent || ""));
        return;
      }
      // Quitar atributos raros
      [...a.attributes].forEach((attr) => {
        const n = attr.name.toLowerCase();
        if (!["href", "target", "rel"].includes(n)) a.removeAttribute(attr.name);
      });
      a.setAttribute("target", "_blank");
      a.setAttribute("rel", "noopener noreferrer");
    });

    return tempDiv.innerHTML;
  }

  function appendMessage(sender, text, isUser = false) {
    const container = document.createElement("div");
    container.className = `mv-message-container ${isUser ? "user" : "bot"}`;

    const now = new Date();
    const time =
      now.getHours().toString().padStart(2, "0") +
      ":" +
      now.getMinutes().toString().padStart(2, "0");

    const sanitizedSender = sanitize(sender);
    const sanitizedText = isUser ? sanitize(text) : sanitizeWithLinks(text);

    container.innerHTML = `
      <div class="mv-message">
        <span class="mv-message-sender">${sanitizedSender}</span>
        <div class="mv-message-text">${sanitizedText}</div>
        <span class="mv-message-time">${time}</span>
      </div>
    `;

    messages.appendChild(container);
    messages.scrollTop = messages.scrollHeight;
  }

  function isQuestionPayload(p) {
    return p && typeof p === "object" && p.type === "question" && Array.isArray(p.buttons);
  }

  function renderButtons(buttons) {
    const wrap = document.createElement("div");
    wrap.className = "mv-buttons-wrap";

    buttons.forEach((btn) => {
      const b = document.createElement("button");
      b.className = "mv-btn-choice";
      b.type = "button";
      b.textContent = btn.label;

      b.onclick = () => {
        appendMessage("Tú", btn.value, true);

        input.disabled = true;
        sendBtn.disabled = true;

        fetch(WEBHOOK_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId,
            message: btn.value,
            page_url: window.location.href,
            ...UTM_DATA
          }),
        })
          .then((r) => r.json())
          .then(handleBotData)
          .catch((err) => {
            console.error(err);
            appendMessage("Asesor", "Lo siento, hubo un error al procesar tu selección. Por favor intenta nuevamente.");
          })
          .finally(() => {
            input.disabled = false;
            sendBtn.disabled = false;
            input.focus();
          });
      };

      wrap.appendChild(b);
    });

    return wrap;
  }

  function handleBotData(data) {
    const payload = Array.isArray(data) ? data[0] : data;

    if (payload && typeof payload === "object" && payload.type) {
      const text = payload.text ?? payload.output ?? payload.message ?? payload.reply ?? "";

      if (text) appendMessage("Asesor", text);

      if (isQuestionPayload(payload)) {
        const lastMsg = messages.lastElementChild;
        if (lastMsg) {
          const msgBox = lastMsg.querySelector(".mv-message");
          if (msgBox) msgBox.appendChild(renderButtons(payload.buttons));
        }
      }

      if (!text && !isQuestionPayload(payload)) {
        appendMessage("Asesor", "Recibí la solicitud, pero no llegó contenido para mostrar.");
      }
      return;
    }

    let response = "";
    if (Array.isArray(data)) {
      response = data[0]?.output ?? data[0]?.message ?? data[0]?.reply ?? "";
    } else {
      response = data?.output ?? data?.reply ?? data?.message ?? "";
    }

    if (response) appendMessage("Asesor", response);
    else appendMessage("Asesor", "Recibí la solicitud, pero no llegó contenido para mostrar.");
  }

  function sendMessage() {
    const userMsg = input.value.trim();
    if (!userMsg) return;

    appendMessage("Tú", userMsg, true);
    input.value = "";
    input.disabled = true;
    sendBtn.disabled = true;

    fetch(WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sessionId,
        message: userMsg,
        page_url: window.location.href,
        ...UTM_DATA
      }),
    })
      .then((r) => r.json())
      .then(handleBotData)
      .catch((err) => {
        console.error(err);
        appendMessage("Asesor", "Lo siento, hubo un error al procesar tu mensaje. Por favor intenta nuevamente.");
      })
      .finally(() => {
        input.disabled = false;
        sendBtn.disabled = false;
        input.focus();
      });
  }

  input.addEventListener("keypress", (e) => {
    if (e.key === "Enter") sendMessage();
  });
  sendBtn.addEventListener("click", sendMessage);
})();

