// ====== 1) Helpers ======
function normalizeText(v) {
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

function firstName(full) {
  const s = String(full || '').trim();
  if (!s) return '';
  return s.split(/\s+/)[0];
}

function titleCase(s) {
  const t = String(s || '').trim();
  if (!t) return '';
  return t.charAt(0).toUpperCase() + t.slice(1);
}

function getSizeLabel(empleadosRaw) {
  const e = normalizeText(empleadosRaw);
  if (e.includes('de 1 a 4')) return 'pequeña';
  if (e.includes('de 5 a 20')) return 'mediana';
  if (e.includes('mas de 20') || e.includes('más de 20')) return 'grande';

  const n = parseInt((e.match(/\d+/)?.[0] || ''), 10);
  if (!isNaN(n)) {
    if (n <= 4) return 'pequeña';
    if (n <= 20) return 'mediana';
    return 'grande';
  }
  return 'mediana';
}

function recommendProduct(empleadosRaw, facturacionRaw) {
  const e = normalizeText(empleadosRaw);
  const f = normalizeText(facturacionRaw);

  const isSmall = e.includes('de 1 a 4');
  const isLow =
    f.includes('aun no facturo') ||
    f.includes('aún no facturo') ||
    f.includes('menos de $100.000') ||
    f.includes('menos de 100.000') ||
    f.includes('menos de 100000') ||
    f.includes('menos de $100000');

  if (isSmall && isLow) {
    return {
      name: 'Mobilvendor One',
      url: 'https://mobilvendor.com/mobilvendor-one',
      sentence: 'una solución ligera ideal para negocios pequeños.'
    };
  }
  return {
    name: 'Mobilvendor Suite',
    url: 'https://mobilvendor.com/mobilvendor-suite',
    sentence: 'una plataforma integral para escalar y controlar tu operación.'
  };
}

function mapIndustriaKey(sectorRaw) {
  const s = normalizeText(sectorRaw);
  if (s.includes('consumo')) return 'Consumo masivo';
  if (s.includes('ferreter')) return 'Ferreteria';
  if (s.includes('farmaceut')) return 'Farmaceutica';
  if (s.includes('automotr')) return 'Automotriz';
  return 'Otro';
}

function industriaNiceName(key) {
  if (key === 'Ferreteria') return 'Ferretería';
  if (key === 'Farmaceutica') return 'Farmacéutica';
  if (key === 'Automotriz') return 'Automotríz';
  return key;
}

function parseModulosToBullets(modulosStr) {
  const cleaned = String(modulosStr || '').trim();
  if (!cleaned) return [];
  const tmp = cleaned.replace(/\s+y\s+/gi, ', ');
  return tmp.split(',').map(x => x.trim()).filter(Boolean);
}

function normalizeModuleName(m) {
  const n = normalizeText(m);

  if (n.includes('logistic')) return 'Logística';
  if (n.includes('facturacion electronica con integracion')) return 'Facturación Electrónica con integración ERP';
  if (n.includes('facturacion electronica')) return 'Facturación Electrónica';
  if (n.includes('inventarios')) return 'Inventarios/WMS';
  if (n.includes('wms')) return 'WMS';
  if (n.includes('reporteria')) return 'Reportería Analítica';
  if (n.includes('merchandising')) return 'Merchandising';
  if (n.includes('contabilidad')) return 'Contabilidad';
  if (n.includes('control de lotes')) return 'Comercial con control de lotes';
  if (n.includes('comercial')) return 'Comercial';
  if (n.includes('back office')) return 'Back Office';

  return titleCase(m);
}

function bulletsFromModuleNames(moduleNames) {
  // Devuelve líneas con "Titulo: descripcion"
  const map = {
    'Comercial': 'Comercial: control de vendedores, pedidos y promociones',
    'Logística': 'Logística: ruteo, entregas y trazabilidad en campo',
    'Facturación Electrónica': 'Facturación electrónica: emisión y control fiscal',
    'Contabilidad': 'Contabilidad: visibilidad financiera y cobranzas',
    'Inventarios/WMS': 'Inventarios/WMS: stock en tiempo real y reducción de quiebres',
    'WMS': 'WMS: control inteligente de bodegas y ubicaciones',
    'Reportería Analítica': 'Reportería analítica: dashboards y KPIs para decisiones estratégicas',
    'Merchandising': 'Merchandising: encuestas, evidencias fotográficas y geolocalización',
    'Facturación Electrónica con integración ERP': 'Facturación electrónica: integración ERP y trazabilidad total',
    'Back Office': 'Back Office: gobernanza de datos y consolidación operativa',
    'Comercial con control de lotes': 'Comercial: control por lotes y trazabilidad regulatoria'
  };
  return moduleNames.map(m => map[m] || m);
}

function makeBoldTitle(line){
  // "Comercial: ..." -> "<b>Comercial:</b> ..."
  const idx = String(line).indexOf(':');
  if (idx === -1) return line;
  const title = line.slice(0, idx + 1);
  const rest = line.slice(idx + 1).trim();
  return `<b>${title}</b> ${rest}`;
