function asMessage(text) {
  return { type: "message", text: text || "" };
}

/**
 * Extrae el primer objeto JSON balanceado "{...}" del texto,
 * tolerando texto antes/después y comillas extra.
 */
function extractFirstJsonObject(text) {
  const start = text.indexOf("{");
  if (start < 0) return null;

  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];

    if (inString) {
      if (escape) {
        escape = false;
      } else if (ch === "\\") {
        escape = true;
      } else if (ch === '"') {
        inString = false;
      }
    } else {
      if (ch === '"') inString = true;
      if (ch === "{") depth++;
      if (ch === "}") depth--;

      if (depth === 0) {
        // encontramos el cierre del objeto JSON
        return text.slice(start, i + 1);
      }
    }
  }
  return null;
}

